// Markdown 관련 유틸리티 함수

/**
 * Markdown 문법을 제거하고 순수 텍스트만 추출
 * @param markdown Markdown 형식의 문자열
 * @returns Markdown 문법이 제거된 순수 텍스트
 */
export const stripMarkdown = (markdown: string): string => {
  if (!markdown) return '';

  let text = markdown;

  // 코드 블록 제거 (```code```)
  text = text.replace(/```[\s\S]*?```/g, '');

  // 인라인 코드 제거 (`code`)
  text = text.replace(/`[^`]*`/g, '');

  // 링크 제거 ([text](url))
  text = text.replace(/\[([^\]]*)\]\([^)]*\)/g, '$1');

  // 이미지 제거 (![alt](url))
  text = text.replace(/!\[([^\]]*)\]\([^)]*\)/g, '');

  // 강조 제거 (**text**, *text*, __text__, _text_)
  text = text.replace(/\*\*([^*]*)\*\*/g, '$1');
  text = text.replace(/\*([^*]*)\*/g, '$1');
  text = text.replace(/__([^_]*)__/g, '$1');
  text = text.replace(/_([^_]*)_/g, '$1');

  // 취소선 제거 (~~text~~)
  text = text.replace(/~~([^~]*)~~/g, '$1');

  // 하이라이트 제거 (==text==)
  text = text.replace(/==([^=]+)==/g, '$1');

  // 헤더 제거 (# text)
  text = text.replace(/^#{1,6}\s+(.*)$/gm, '$1');

  // 리스트 마커 제거 (-, *, +, 1.)
  text = text.replace(/^[\s]*[-*+]\s+/gm, '');
  text = text.replace(/^[\s]*\d+\.\s+/gm, '');

  // 인용문 제거 (> text)
  text = text.replace(/^>\s+(.*)$/gm, '$1');

  // 수평선 제거 (---, ***)
  text = text.replace(/^[-*]{3,}$/gm, '');

  // HTML 태그 제거 (기본적인 것들)
  text = text.replace(/<[^>]*>/g, '');

  // 여러 공백을 하나로
  text = text.replace(/\s+/g, ' ');

  // 앞뒤 공백 제거
  text = text.trim();

  return text;
};

/**
 * Markdown에서 미리보기용 텍스트 추출
 * @param markdown Markdown 형식의 문자열
 * @param maxLength 최대 길이 (기본값: 100)
 * @returns 미리보기 텍스트
 */
export const getPlainTextPreview = (markdown: string, maxLength: number = 100): string => {
  if (!markdown) return '';

  const plainText = stripMarkdown(markdown);

  if (plainText.length <= maxLength) {
    return plainText;
  }

  return plainText.substring(0, maxLength) + '...';
};
