import React, { useState, useRef } from 'react';
import MDEditor from '@uiw/react-md-editor';
import '@uiw/react-md-editor/markdown-editor.css';
import { uploadManualImage, validateImageFile } from '../utils/manualImageApi';
import { useToast } from '../hooks/useToast';

interface MarkdownEditorProps {
  value: string;
  onChange: (value: string | undefined) => void;
  disabled?: boolean;
  error?: boolean;
  placeholder?: string;
}

const MarkdownEditor: React.FC<MarkdownEditorProps> = ({
  value,
  onChange,
  disabled = false,
  error = false,
  placeholder = 'Markdown 형식으로 작성하세요...',
}) => {
  const [isUploading, setIsUploading] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const editorRef = useRef<HTMLDivElement>(null);
  const { showToast } = useToast();

  // 파일 업로드 처리
  const handleFileUpload = async (file: File) => {
    // 파일 타입 검증
    if (!validateImageFile(file)) {
      showToast('이미지 또는 PDF 파일만 업로드할 수 있습니다.', 'error');
      return;
    }

    try {
      setIsUploading(true);
      const response = await uploadManualImage(file);
      if (response.success && response.data.imageUrl) {
        // 마크다운 형식으로 이미지 URL 삽입
        const imageMarkdown = `![${file.name}](${response.data.imageUrl})`;
        const currentValue = value || '';
        const newValue = currentValue + (currentValue ? '\n\n' : '') + imageMarkdown;
        onChange(newValue);
        showToast('이미지가 업로드되었습니다.', 'success');
      }
    } catch (err) {
      showToast(
        err instanceof Error ? err.message : '이미지 업로드에 실패했습니다.',
        'error'
      );
    } finally {
      setIsUploading(false);
    }
  };

  // 드래그 오버 핸들러
  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (!disabled && !isUploading) {
      setIsDragging(true);
    }
  };

  // 드래그 리브 핸들러
  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);
  };

  // 드롭 핸들러
  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);

    if (disabled || isUploading) return;

    const files = Array.from(e.dataTransfer.files);
    if (files.length > 0) {
      // 첫 번째 파일만 처리
      handleFileUpload(files[0]);
    }
  };

  // 파일 입력 핸들러 (클릭으로 파일 선택)
  const handleFileInput = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (files && files.length > 0) {
      handleFileUpload(files[0]);
    }
    // 같은 파일을 다시 선택할 수 있도록 input 초기화
    e.target.value = '';
  };

  return (
    <div
      ref={editorRef}
      className={`relative ${error ? 'border-2 border-red-500 rounded-lg' : ''} ${
        isDragging ? 'ring-2 ring-blue-500 ring-offset-2' : ''
      }`}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
    >
      {/* 드래그 오버 오버레이 */}
      {isDragging && (
        <div className="absolute inset-0 z-10 bg-blue-50 bg-opacity-90 flex items-center justify-center border-2 border-dashed border-blue-500 rounded-lg">
          <div className="text-center">
            <svg
              className="w-12 h-12 mx-auto text-blue-500 mb-2"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12"
              />
            </svg>
            <p className="text-blue-600 font-medium">이미지를 여기에 놓으세요</p>
          </div>
        </div>
      )}

      {/* 업로드 중 오버레이 */}
      {isUploading && (
        <div className="absolute inset-0 z-10 bg-white bg-opacity-90 flex items-center justify-center rounded-lg">
          <div className="text-center">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600 mx-auto mb-2"></div>
            <p className="text-gray-600">이미지 업로드 중...</p>
          </div>
        </div>
      )}

      <div data-color-mode="light" className="h-full">
        <style>{`
          .w-md-editor {
            height: 100% !important;
          }
          .w-md-editor-text-pre {
            height: 100% !important;
          }
        `}</style>
        <MDEditor
          value={value}
          onChange={onChange}
          preview="edit"
          hideToolbar={false}
          visibleDragbar={true}
          textareaProps={{
            placeholder,
            disabled: disabled || isUploading,
            style: {
              fontSize: 14,
            },
          }}
        />
      </div>

      {/* 파일 입력 (숨김) */}
      <input
        type="file"
        accept="image/*,.pdf"
        onChange={handleFileInput}
        disabled={disabled || isUploading}
        className="hidden"
        id={`markdown-editor-file-input-${editorRef.current?.id || 'default'}`}
      />
    </div>
  );
};

export default MarkdownEditor;
