import React, { useRef, useEffect } from 'react';

interface AnnouncementDeleteConfirmModalProps {
  isOpen: boolean;
  title: string;
  onConfirm: () => void;
  onCancel: () => void;
  isProcessing: boolean;
}

const AnnouncementDeleteConfirmModal: React.FC<AnnouncementDeleteConfirmModalProps> = ({
  isOpen,
  title,
  onConfirm,
  onCancel,
  isProcessing,
}) => {
  const modalRef = useRef<HTMLDivElement>(null);

  // ESC 키 감지
  useEffect(() => {
    const handleEscapeKey = (event: KeyboardEvent) => {
      if (event.key === 'Escape' && !isProcessing) {
        onCancel();
      }
    };

    if (isOpen) {
      document.addEventListener('keydown', handleEscapeKey);
    }

    return () => {
      document.removeEventListener('keydown', handleEscapeKey);
    };
  }, [isOpen, onCancel, isProcessing]);

  if (!isOpen) {
    return null;
  }

  return (
    <div 
      className="fixed inset-0 bg-black bg-opacity-50 z-[60] flex items-center justify-center p-4"
      onClick={(e) => {
        // 배경 딤 클릭 시 모달 닫기 방지 (모달 내부 클릭만 허용)
        if (e.target === e.currentTarget && !isProcessing) {
          onCancel();
        }
      }}
    >
      {/* 모달 */}
      <div
        ref={modalRef}
        className="bg-white rounded-lg shadow-xl w-full max-w-md animate-fade-in"
        onClick={(e) => e.stopPropagation()}
      >
        {/* 헤더 */}
        <div className="flex items-center justify-between p-4 border-b border-gray-200">
          <h3 className="text-lg font-medium text-gray-900">공지사항 삭제</h3>
          <button
            onClick={onCancel}
            disabled={isProcessing}
            className="text-gray-400 hover:text-gray-600 transition-colors disabled:opacity-50"
            aria-label="모달 닫기"
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        {/* 내용 */}
        <div className="p-6">
          <p className="text-gray-700 mb-4">
            다음 공지사항을 삭제하시겠습니까?
          </p>
          <p className="text-sm font-semibold text-gray-900 mb-4 bg-gray-50 p-3 rounded">
            {title}
          </p>
          <p className="text-sm text-red-600">
            삭제된 공지사항은 복구할 수 없습니다.
          </p>
        </div>

        {/* 하단 버튼 */}
        <div className="flex justify-end gap-3 p-4 border-t border-gray-200">
          <button
            onClick={onCancel}
            disabled={isProcessing}
            className="px-4 py-2 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
          >
            취소
          </button>
          <button
            onClick={onConfirm}
            disabled={isProcessing}
            className="px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {isProcessing ? '삭제 중...' : '삭제'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default AnnouncementDeleteConfirmModal;
