import {
  AdminResponse,
  ApiResponse,
  ApproveRequest,
  FieldError,
  HostApplicationListParams,
  HostApplicationListResult,
  HostApplicationQrStatus,
  ResultView,
} from '../types/hostApplication';

const getApiBaseUrl = () => {
  if (process.env.NODE_ENV === 'development') {
    return process.env.REACT_APP_API_URL || 'http://localhost:8084';
  }
  return process.env.REACT_APP_API_URL || 'https://api.brainbackdoor.com';
};

const API_BASE_URL = getApiBaseUrl();

const getServerAuthHeader = (): string =>
  process.env.REACT_APP_SERVER_AUTH || 'secret';

const getHeaders = (includeJson = true): HeadersInit => {
  const h: Record<string, string> = {
    Accept: 'application/json',
    'X-SERVER-AUTH': getServerAuthHeader(),
  };
  if (includeJson) {
    h['Content-Type'] = 'application/json';
  }
  return h;
};

export class HostApplicationApiError extends Error {
  readonly status: number;
  readonly code?: string;
  readonly fieldErrors?: FieldError[];
  readonly isResultView: boolean;
  readonly rawBody: unknown;

  constructor(
    message: string,
    status: number,
    options?: {
      code?: string;
      fieldErrors?: FieldError[];
      isResultView?: boolean;
      rawBody?: unknown;
    }
  ) {
    super(message);
    this.name = 'HostApplicationApiError';
    this.status = status;
    this.code = options?.code;
    this.fieldErrors = options?.fieldErrors;
    this.isResultView = options?.isResultView ?? false;
    this.rawBody = options?.rawBody;
  }
}

async function parseJsonSafe(response: Response): Promise<unknown> {
  const text = await response.text();
  if (!text) return null;
  try {
    return JSON.parse(text);
  } catch {
    return null;
  }
}

function isRecord(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function throwFromResponse(status: number, json: unknown): never {
  if (isRecord(json) && json.success === false) {
    const message =
      typeof json.message === 'string' ? json.message : `요청 실패 (${status})`;
    if ('body' in json && !('errors' in json)) {
      throw new HostApplicationApiError(message, status, {
        isResultView: true,
        rawBody: json,
      });
    }
    const code = typeof json.code === 'string' ? json.code : undefined;
    const errors = Array.isArray(json.errors) ? (json.errors as FieldError[]) : undefined;
    throw new HostApplicationApiError(message, status, {
      code,
      fieldErrors: errors,
      isResultView: false,
      rawBody: json,
    });
  }
  throw new HostApplicationApiError(`HTTP ${status}`, status, { rawBody: json });
}

function buildListQuery(params: HostApplicationListParams): string {
  const sp = new URLSearchParams();
  if (params.status) sp.set('status', params.status);
  if (params.qr_status) sp.set('qr_status', params.qr_status);
  if (params.limit != null) sp.set('limit', String(params.limit));
  if (params.cursor) sp.set('cursor', params.cursor);
  const s = sp.toString();
  return s ? `?${s}` : '';
}

export async function fetchHostApplicationsList(
  params: HostApplicationListParams = {}
): Promise<HostApplicationListResult> {
  const url = `${API_BASE_URL}/api/host-applications${buildListQuery(params)}`;
  const response = await fetch(url, {
    method: 'GET',
    headers: getHeaders(false),
    mode: 'cors',
  });
  const json = await parseJsonSafe(response);
  if (!response.ok) {
    throwFromResponse(response.status, json);
  }
  const wrapped = json as ApiResponse<AdminResponse[]> & {
    has_more?: boolean;
    next_cursor?: string;
  };
  if (!wrapped?.success || !Array.isArray(wrapped.data)) {
    throw new HostApplicationApiError('목록 응답 형식이 올바르지 않습니다.', response.status, {
      rawBody: json,
    });
  }
  const hasMore = wrapped.has_more === true;
  const nextCursor =
    hasMore && typeof wrapped.next_cursor === 'string' ? wrapped.next_cursor : null;
  return {
    items: wrapped.data,
    hasMore,
    nextCursor,
  };
}

/** @deprecated 내부적으로 fetchHostApplicationsList 사용 권장 */
export async function listHostApplications(
  status?: string
): Promise<AdminResponse[]> {
  const r = await fetchHostApplicationsList(status ? { status } : {});
  return r.items;
}

export async function patchHostApplicationQrStatus(
  id: string,
  qr_status: HostApplicationQrStatus
): Promise<AdminResponse> {
  const url = `${API_BASE_URL}/api/host-applications/${encodeURIComponent(id)}/qr-status`;
  const response = await fetch(url, {
    method: 'PATCH',
    headers: getHeaders(true),
    mode: 'cors',
    body: JSON.stringify({ qr_status }),
  });
  const json = await parseJsonSafe(response);
  if (!response.ok) {
    throwFromResponse(response.status, json);
  }
  const wrapped = json as ApiResponse<AdminResponse>;
  if (!wrapped?.success || !wrapped.data) {
    throw new HostApplicationApiError('QR 상태 응답 형식이 올바르지 않습니다.', response.status, {
      rawBody: json,
    });
  }
  return wrapped.data;
}

/** 목록·일괄 처리: null/누락은 서버와 동일하게 NOT_STARTED로 간주 */
export function normalizeEffectiveQrStatus(
  qr_status: HostApplicationQrStatus | null | undefined
): HostApplicationQrStatus {
  if (qr_status == null) return 'NOT_STARTED';
  return qr_status;
}

/** 다음 단계 PATCH 대상. QR_SENT면 null(요청 생략) */
export function getNextQrStatusForPatch(
  current: HostApplicationQrStatus
): HostApplicationQrStatus | null {
  if (current === 'NOT_STARTED') return 'QR_GENERATED';
  if (current === 'QR_GENERATED') return 'QR_SENT';
  return null;
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

const QR_PATCH_RETRY_DELAYS_MS = [200, 400, 800];

/** 네트워크·5xx·429만 재시도 대상 (4xx 비즈니스 오류 제외) */
export function isTransientHostApplicationFailure(error: unknown): boolean {
  if (error instanceof TypeError) return true;
  if (!(error instanceof HostApplicationApiError)) return false;
  if (error.status >= 500) return true;
  if (error.status === 429) return true;
  return false;
}

/**
 * QR PATCH — 일시 오류 시 최대 maxRetries번 재시도(기본 3 → 총 시도 4회).
 */
export async function patchHostApplicationQrStatusWithRetries(
  id: string,
  qr_status: HostApplicationQrStatus,
  options?: { maxRetries?: number }
): Promise<AdminResponse> {
  const maxRetries = options?.maxRetries ?? 3;
  let lastError: unknown;
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      return await patchHostApplicationQrStatus(id, qr_status);
    } catch (e) {
      lastError = e;
      if (attempt >= maxRetries || !isTransientHostApplicationFailure(e)) {
        throw e;
      }
      await sleep(QR_PATCH_RETRY_DELAYS_MS[attempt] ?? 800);
    }
  }
  throw lastError;
}

export async function getHostApplication(id: string): Promise<AdminResponse> {
  const url = `${API_BASE_URL}/api/host-applications/${encodeURIComponent(id)}`;
  const response = await fetch(url, {
    method: 'GET',
    headers: getHeaders(false),
    mode: 'cors',
  });
  const json = await parseJsonSafe(response);
  if (!response.ok) {
    throwFromResponse(response.status, json);
  }
  const wrapped = json as ApiResponse<AdminResponse>;
  if (!wrapped?.success || !wrapped.data) {
    throw new HostApplicationApiError('상세 응답 형식이 올바르지 않습니다.', response.status, {
      rawBody: json,
    });
  }
  return wrapped.data;
}

/** ApproveRequest JSON 직렬화 — 빈 선택 필드는 키 제외 */
export function serializeApproveRequest(body: ApproveRequest): string {
  const o: Record<string, unknown> = {
    address: body.address.trim(),
    lat: body.lat,
    lng: body.lng,
    stay_name: body.stay_name.trim(),
  };
  const d = body.detail_address;
  if (d !== undefined && d !== null && String(d).trim() !== '') {
    o.detail_address = String(d).trim();
  }
  const n = body.note;
  if (n !== undefined && n !== null && String(n).trim() !== '') {
    o.note = String(n).trim();
  }
  const di = body.display_info;
  if (di !== undefined && di !== null && String(di).trim() !== '') {
    o.display_info = String(di).trim();
  }
  return JSON.stringify(o);
}

export async function approveHostApplication(
  id: string,
  body: ApproveRequest
): Promise<AdminResponse> {
  const url = `${API_BASE_URL}/api/host-applications/${encodeURIComponent(id)}/approve`;
  const response = await fetch(url, {
    method: 'PUT',
    headers: getHeaders(true),
    mode: 'cors',
    body: serializeApproveRequest(body),
  });
  const json = await parseJsonSafe(response);
  if (!response.ok) {
    throwFromResponse(response.status, json);
  }
  const wrapped = json as ApiResponse<AdminResponse>;
  if (!wrapped?.success || !wrapped.data) {
    throw new HostApplicationApiError('승인 응답 형식이 올바르지 않습니다.', response.status, {
      rawBody: json,
    });
  }
  return wrapped.data;
}

