import React, { useRef, useEffect } from 'react';

interface BankbookImageModalProps {
  isOpen: boolean;
  imageUrl: string;
  onClose: () => void;
}

const BankbookImageModal: React.FC<BankbookImageModalProps> = ({
  isOpen,
  imageUrl,
  onClose,
}) => {
  const modalRef = useRef<HTMLDivElement>(null);

  // 외부 클릭 감지
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (modalRef.current && !modalRef.current.contains(event.target as Node)) {
        onClose();
      }
    };

    if (isOpen) {
      document.addEventListener('mousedown', handleClickOutside);
    }

    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [isOpen, onClose]);

  // ESC 키 감지
  useEffect(() => {
    const handleEscapeKey = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        onClose();
      }
    };

    if (isOpen) {
      document.addEventListener('keydown', handleEscapeKey);
    }

    return () => {
      document.removeEventListener('keydown', handleEscapeKey);
    };
  }, [isOpen, onClose]);

  if (!isOpen) {
    return null;
  }

  return (
    <>
      {/* 배경 딤 */}
      <div className="fixed inset-0 bg-black bg-opacity-75 z-50 flex items-center justify-center p-4">
        {/* 모달 */}
        <div
          ref={modalRef}
          className="bg-white rounded-lg shadow-xl max-w-[90vw] max-h-[90vh] animate-fade-in relative"
        >
          {/* 닫기 버튼 */}
          <button
            onClick={onClose}
            className="absolute top-4 right-4 z-10 text-white bg-black bg-opacity-50 hover:bg-opacity-70 rounded-full p-2 transition-colors"
            aria-label="모달 닫기"
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>

          {/* 이미지 또는 PDF */}
          {imageUrl.toLowerCase().endsWith('.pdf') || imageUrl.includes('application/pdf') ? (
            <iframe
              src={imageUrl}
              className="w-full h-[90vh] rounded-lg"
              title="PDF 뷰어"
            />
          ) : (
            <img
              src={imageUrl}
              alt="통장사본"
              className="max-w-full max-h-[90vh] object-contain rounded-lg"
            />
          )}
        </div>
      </div>
    </>
  );
};

export default BankbookImageModal;

