import React, { useState, useRef, useEffect } from 'react';
import { useOrderKey } from '../../hooks/useOrderKey';

const SHEET_BASE_PATH = '/sheet';

const MoreMenu: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);
  const { getNavigationPath } = useOrderKey();

  // 외부 클릭 시 메뉴 닫기
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (
        menuRef.current && 
        buttonRef.current && 
        !menuRef.current.contains(event.target as Node) &&
        !buttonRef.current.contains(event.target as Node)
      ) {
        setIsOpen(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  const toggleMenu = () => {
    setIsOpen(!isOpen);
  };

  const getMenuItemHref = (path: string) => {
    const targetPath = getNavigationPath(path);
    return `${SHEET_BASE_PATH}${targetPath.startsWith('/') ? '' : '/'}${targetPath}`;
  };

  const MenuItem = ({ path, children }: { path: string; children: React.ReactNode }) => {
    return (
      <a
        href={getMenuItemHref(path)}
        target="_blank"
        rel="noopener noreferrer"
        onClick={() => setIsOpen(false)}
        className="w-full px-4 py-3 text-left hover:bg-gray-50 transition-colors duration-150 flex items-center"
      >
        {children}
      </a>
    );
  };

  return (
    <div className="relative">
      {/* 더보기 버튼 */}
      <button
        ref={buttonRef}
        onClick={toggleMenu}
        className="w-12 h-12 bg-gray-100 hover:bg-gray-200 rounded-full flex items-center justify-center transition-colors duration-200 ml-3"
        aria-label="더보기 메뉴"
      >
        <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor" className="text-gray-600">
          <path d="M12 8c1.1 0 2-.9 2-2s-.9-2-2-2-2 .9-2 2 .9 2 2 2zm0 2c-1.1 0-2 .9-2 2s.9 2 2 2 2-.9 2-2-.9-2-2-2zm0 6c-1.1 0-2 .9-2 2s.9 2 2 2 2-.9 2-2-.9-2-2-2z"/>
        </svg>
      </button>

      {/* 드롭다운 메뉴 */}
      {isOpen && (
        <div
          ref={menuRef}
          className="absolute right-0 top-full mt-2 w-48 bg-white rounded-lg shadow-lg border border-gray-200 py-2 z-50"
        >
          {/* 위쪽 화살표 */}
          <div className="absolute -top-2 right-4 w-4 h-4 bg-white border-l border-t border-gray-200 transform rotate-45"></div>
          
          {/* 메뉴 항목들 */}
          <MenuItem path="/">
            <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor" className="text-gray-500 mr-3">
              <path d="M10 20v-6h4v6h5v-8h3L12 3 2 12h3v8z"/>
            </svg>
            <span className="text-gray-700">홈</span>
          </MenuItem>
          
          <MenuItem path="/host-management">
            <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor" className="text-gray-500 mr-3">
              <path d="M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z"/>
            </svg>
            <span className="text-gray-700">Host 관리</span>
          </MenuItem>

          <MenuItem path="/host-applications">
            <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor" className="text-gray-500 mr-3">
              <path d="M19 3H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zm-2 10H7v-2h10v2zm0-4H7V7h10v2z"/>
            </svg>
            <span className="text-gray-700">호스트 신청</span>
          </MenuItem>
          
          <MenuItem path="/stay-management">
            <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor" className="text-gray-500 mr-3">
              <path d="M19 3H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zm-7 14H6v-2h6v2zm4-4H6v-2h10v2zm0-4H6V7h10v2z"/>
            </svg>
            <span className="text-gray-700">Stay 관리</span>
          </MenuItem>
          
          <MenuItem path="/add-stay">
            <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor" className="text-gray-500 mr-3">
              <path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7zm0 9.5c-1.38 0-2.5-1.12-2.5-2.5s1.12-2.5 2.5-2.5 2.5 1.12 2.5 2.5-1.12 2.5-2.5 2.5z"/>
            </svg>
            <span className="text-gray-700">Stay 추가</span>
          </MenuItem>
          
          <MenuItem path="/host-funnel">
            <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor" className="text-gray-500 mr-3">
              <path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z"/>
            </svg>
            <span className="text-gray-700">호스트 퍼널</span>
          </MenuItem>
          
          <MenuItem path="/settlement">
            <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor" className="text-gray-500 mr-3">
              <path d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/>
            </svg>
            <span className="text-gray-700">정산 목록</span>
          </MenuItem>
          
          <MenuItem path="/admin-settlement">
            <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor" className="text-gray-500 mr-3">
              <path d="M19 3H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zm-7 14H6v-2h6v2zm4-4H6v-2h10v2zm0-4H6V7h10v2z"/>
            </svg>
            <span className="text-gray-700">정산 요청 관리</span>
          </MenuItem>
          
          <MenuItem path="/menu-prices">
            <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor" className="text-gray-500 mr-3">
              <path d="M21.41 11.58l-9-9C12.05 2.22 11.55 2 11 2H4c-1.1 0-2 .9-2 2v7c0 .55.22 1.05.59 1.42l9 9c.36.36.86.58 1.41.58s1.05-.22 1.41-.59l7-7c.37-.36.59-.86.59-1.41s-.23-1.06-.59-1.42zM5.5 7C4.67 7 4 6.33 4 5.5S4.67 4 5.5 4 7 4.67 7 5.5 6.33 7 5.5 7z"/>
            </svg>
            <span className="text-gray-700">메뉴 가격 관리</span>
          </MenuItem>

          <MenuItem path="/promotions">
            <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor" className="text-gray-500 mr-3">
              <path d="M20 6h-3V4a2 2 0 00-2-2H9a2 2 0 00-2 2v2H4a2 2 0 00-2 2v3h20V8a2 2 0 00-2-2zm-5-2v2H9V4h6zM2 13v5a2 2 0 002 2h16a2 2 0 002-2v-5h-8v2h-4v-2H2z"/>
            </svg>
            <span className="text-gray-700">프로모션 관리</span>
          </MenuItem>
          
          <MenuItem path="/announcements">
            <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor" className="text-gray-500 mr-3">
              <path d="M20 4H4c-1.1 0-1.99.9-1.99 2L2 18c0 1.1.9 2 2 2h16c1.1 0 2-.9 2-2V6c0-1.1-.9-2-2-2zm0 4l-8 5-8-5V6l8 5 8-5v2z"/>
            </svg>
            <span className="text-gray-700">공지사항</span>
          </MenuItem>
          
          <MenuItem path="/manuals">
            <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor" className="text-gray-500 mr-3">
              <path d="M19 3H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zM9 17H7v-7h2v7zm4 0h-2V7h2v10zm4 0h-2v-4h2v4z"/>
            </svg>
            <span className="text-gray-700">메뉴얼</span>
          </MenuItem>

        </div>
      )}
    </div>
  );
};

export default MoreMenu;
