import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { HostListItem, HostStay, StayManagementItem } from '../types';
import { getHostList, updateStayActive } from '../utils/hostApi';
import { useToast } from '../hooks/useToast';
import { formatDate } from '../utils/dateUtils';
import { loadPosterImage, composePosterPage, downloadBatchPosterPdf, PosterPageData } from '../utils/posterUtils';
import { QRCodeCanvas } from 'qrcode.react';
import LoadingSpinner from '../components/LoadingSpinner';
import ErrorMessage from '../components/ErrorMessage';
import StayQRCodeModal from '../components/StayQRCodeModal';

// HostListItem[]을 StayManagementItem[]으로 flatten
const flattenHostListToStays = (hostList: HostListItem[]): StayManagementItem[] => {
  const items: StayManagementItem[] = [];
  for (const hostItem of hostList) {
    for (const stay of hostItem.stays) {
      items.push({
        id: stay.id,
        addressId: stay.addressId,
        stayName: stay.stayName,
        stayId: stay.stayId,
        note: stay.note,
        displayInfo: stay.displayInfo,
        hostId: stay.hostId,
        installationDate: stay.installationDate,
        createdDate: stay.createdDate,
        updatedDate: stay.updatedDate,
        active: stay.active,
        hostName: hostItem.host.hostName,
      });
    }
  }
  return items;
};

const StayManagementPage: React.FC = () => {
  const [hostList, setHostList] = useState<HostListItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // 펼침 상태 (displayInfo 토글)
  const [expandedIds, setExpandedIds] = useState<Set<string>>(new Set());

  // QR 모달 상태
  const [selectedStay, setSelectedStay] = useState<HostStay | null>(null);
  const [qrModalOpen, setQrModalOpen] = useState(false);

  // 체크박스 선택 상태 (배열 순서 = 선택 순서)
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [isBatchDownloading, setIsBatchDownloading] = useState(false);

  // 숨김 QR 캔버스 컨테이너 ref
  const qrContainerRef = useRef<HTMLDivElement>(null);

  // 활성/비활성 토글 상태
  const [togglingIds, setTogglingIds] = useState<Set<string>>(new Set());
  const [confirmDeactivate, setConfirmDeactivate] = useState<StayManagementItem | null>(null);

  const { showToast } = useToast();

  const copyToClipboard = useCallback(async (text: string, label: string, particle: '이' | '가') => {
    try {
      await navigator.clipboard.writeText(text);
      showToast(`${label}${particle} 복사되었습니다.`, 'success');
    } catch {
      showToast(`${label} 복사에 실패했습니다.`, 'error');
    }
  }, [showToast]);

  // 데이터 조회
  const fetchData = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);
      const response = await getHostList();
      if (response.success) {
        setHostList(response.data);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Stay 목록을 불러오는데 실패했습니다.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  // flatten + 정렬 + 검색 필터
  const stayList = useMemo(() => {
    let items = flattenHostListToStays(hostList);

    // 검색 필터
    if (searchTerm) {
      const term = searchTerm.toLowerCase();
      items = items.filter(
        (item) =>
          item.stayName.toLowerCase().includes(term) ||
          item.hostName.toLowerCase().includes(term) ||
          (item.note && item.note.toLowerCase().includes(term))
      );
    }

    // createdDate 내림차순 정렬
    items.sort((a, b) => {
      const aTime = new Date(a.createdDate).getTime();
      const bTime = new Date(b.createdDate).getTime();
      return bTime - aTime;
    });

    return items;
  }, [hostList, searchTerm]);

  // 펼침 토글
  const toggleExpand = (id: string) => {
    setExpandedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) {
        next.delete(id);
      } else {
        next.add(id);
      }
      return next;
    });
  };

  // QR 모달 열기 (StayManagementItem → HostStay 변환)
  const handleQRCodeClick = (item: StayManagementItem) => {
    const hostStay: HostStay = {
      id: item.id,
      addressId: item.addressId,
      stayName: item.stayName,
      stayId: item.stayId,
      note: item.note,
      displayInfo: item.displayInfo,
      hostId: item.hostId,
      installationDate: item.installationDate,
      createdDate: item.createdDate,
      updatedDate: item.updatedDate,
      active: item.active,
    };
    setSelectedStay(hostStay);
    setQrModalOpen(true);
  };

  const handleQRModalClose = () => {
    setQrModalOpen(false);
    setSelectedStay(null);
  };

  // 전체 선택 / 해제
  const handleSelectAll = () => {
    if (selectedIds.length === stayList.length) {
      setSelectedIds([]);
    } else {
      setSelectedIds(stayList.map((item) => item.id));
    }
  };

  // 개별 선택 토글
  const handleSelectItem = (id: string) => {
    setSelectedIds((prev) =>
      prev.includes(id) ? prev.filter((v) => v !== id) : [...prev, id]
    );
  };

  // 일괄 포스터 다운로드
  const handleBatchPosterDownload = async () => {
    if (!qrContainerRef.current || selectedIds.length === 0) return;

    setIsBatchDownloading(true);
    try {
      const posterImg = await loadPosterImage();

      const stayMap = new Map(stayList.map((item) => [item.id, item]));
      const selectedStays = selectedIds
        .map((id) => stayMap.get(id))
        .filter((item): item is StayManagementItem => item !== undefined);

      const pages: PosterPageData[] = [];
      for (const stay of selectedStays) {
        const container = qrContainerRef.current.querySelector(
          `[data-stay-id="${stay.stayId}"]`
        );
        const qrCanvas = container?.querySelector('canvas');
        if (qrCanvas) {
          pages.push(composePosterPage(posterImg, qrCanvas as HTMLCanvasElement, stay.stayName));
        }
      }

      if (pages.length > 0) {
        downloadBatchPosterPdf(
          pages,
          `Posters_${new Date().toISOString().slice(0, 10)}.pdf`
        );
        showToast(`${pages.length}개 포스터가 다운로드되었습니다.`, 'success');
      }
    } catch (error) {
      showToast(
        error instanceof Error ? error.message : '포스터 다운로드에 실패했습니다.',
        'error'
      );
    } finally {
      setIsBatchDownloading(false);
    }
  };

  // 활성/비활성 토글 핸들러
  const handleToggleActive = useCallback(async (item: StayManagementItem, newActive: boolean) => {
    setTogglingIds((prev) => new Set(prev).add(item.id));
    try {
      await updateStayActive(item.id, newActive);
      setHostList((prev) =>
        prev.map((hostItem) => ({
          ...hostItem,
          stays: hostItem.stays.map((stay) =>
            stay.id === item.id ? { ...stay, active: newActive } : stay
          ),
        }))
      );
      showToast(
        newActive ? `${item.stayName} 활성화되었습니다.` : `${item.stayName} 비활성화되었습니다.`,
        'success'
      );
    } catch (err) {
      showToast(
        err instanceof Error ? err.message : '상태 변경에 실패했습니다.',
        'error'
      );
    } finally {
      setTogglingIds((prev) => {
        const next = new Set(prev);
        next.delete(item.id);
        return next;
      });
    }
  }, [showToast]);

  const handleToggleClick = useCallback((item: StayManagementItem) => {
    const newActive = item.active !== true;
    if (!newActive) {
      setConfirmDeactivate(item);
    } else {
      handleToggleActive(item, newActive);
    }
  }, [handleToggleActive]);

  const handleConfirmDeactivate = useCallback(() => {
    if (confirmDeactivate) {
      handleToggleActive(confirmDeactivate, false);
      setConfirmDeactivate(null);
    }
  }, [confirmDeactivate, handleToggleActive]);

  return (
    <div>
      <div className="mx-auto px-4 py-6">
        <h1 className="text-2xl font-bold text-gray-900 mb-6">Stay 관리</h1>

        {loading && <LoadingSpinner />}

        {error && <ErrorMessage message={error} onRetry={fetchData} />}

        {!loading && !error && (
          <>
            {/* 검색 + 건수 + 일괄 다운로드 */}
            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 mb-4">
              <div className="relative flex-1 max-w-md">
                <input
                  type="text"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  placeholder="Stay명, 호스트명, 메모 검색..."
                  className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent text-sm"
                />
                <svg
                  className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"
                  />
                </svg>
              </div>
              <div className="flex items-center gap-3">
                {selectedIds.length > 0 && (
                  <button
                    onClick={handleBatchPosterDownload}
                    disabled={isBatchDownloading}
                    title="선택한 순서대로 포스터 PDF가 생성됩니다"
                    className="px-4 py-2 bg-emerald-600 text-white text-sm rounded-lg hover:bg-emerald-700 transition-colors flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                    </svg>
                    {isBatchDownloading
                      ? '생성 중...'
                      : `선택 포스터 다운로드 (${selectedIds.length})`}
                  </button>
                )}
                <span className="text-sm text-gray-500 whitespace-nowrap">
                  총 {stayList.length}개
                </span>
              </div>
            </div>

            {stayList.length > 0 ? (
              <>
                {/* ── 데스크톱 테이블 (md 이상) ── */}
                <div className="hidden md:block bg-white rounded-lg shadow-sm border border-gray-200 overflow-hidden">
                  <div className="overflow-x-auto">
                    <table className="w-full divide-y divide-gray-200" style={{ minWidth: '900px' }}>
                      <thead className="bg-gray-50">
                        <tr>
                          <th className="px-3 py-3 text-center w-10">
                            <input
                              type="checkbox"
                              checked={stayList.length > 0 && selectedIds.length === stayList.length}
                              onChange={handleSelectAll}
                              className="w-4 h-4 text-blue-600 rounded border-gray-300 focus:ring-blue-500 cursor-pointer"
                            />
                          </th>
                          <th className="px-2 py-3 w-8"></th>
                          <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider whitespace-nowrap">
                            Stay명
                          </th>
                          <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider whitespace-nowrap">
                            메모
                          </th>
                          <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider whitespace-nowrap">
                            호스트명
                          </th>
                          <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider whitespace-nowrap">
                            생성일
                          </th>
                          <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider whitespace-nowrap">
                            설치일
                          </th>
                          <th className="px-4 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider whitespace-nowrap">
                            상태
                          </th>
                          <th className="px-4 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider whitespace-nowrap">
                            QR / 포스터
                          </th>
                        </tr>
                      </thead>
                      <tbody className="bg-white divide-y divide-gray-200">
                        {stayList.map((item) => (
                          <React.Fragment key={item.id}>
                            <tr className={`hover:bg-gray-50 transition-colors ${item.active === false ? 'opacity-50' : ''}`}>
                              {/* 체크박스 + 선택 순서 */}
                              <td className="px-3 py-3">
                                <div className="flex items-center justify-center gap-1.5">
                                  <input
                                    type="checkbox"
                                    checked={selectedIds.includes(item.id)}
                                    onChange={() => handleSelectItem(item.id)}
                                    className="w-4 h-4 text-blue-600 rounded border-gray-300 focus:ring-blue-500 cursor-pointer"
                                  />
                                  {selectedIds.includes(item.id) && (
                                    <span className="inline-flex items-center justify-center w-5 h-5 rounded-full bg-emerald-500 text-white text-[10px] font-bold leading-none">
                                      {selectedIds.indexOf(item.id) + 1}
                                    </span>
                                  )}
                                </div>
                              </td>
                              {/* 펼침 버튼 */}
                              <td className="px-2 py-3">
                                {item.displayInfo && (
                                  <button
                                    onClick={() => toggleExpand(item.id)}
                                    className="p-1 text-gray-400 hover:text-gray-600 rounded transition-colors"
                                    title="표시 정보 보기"
                                  >
                                    <svg
                                      className={`w-4 h-4 transform transition-transform ${
                                        expandedIds.has(item.id) ? 'rotate-90' : ''
                                      }`}
                                      fill="currentColor"
                                      viewBox="0 0 20 20"
                                    >
                                      <path
                                        fillRule="evenodd"
                                        d="M7.293 14.707a1 1 0 010-1.414L10.586 10 7.293 6.707a1 1 0 111.414-1.414l4 4a1 1 0 010 1.414l-4 4a1 1 0 01-1.414 0z"
                                        clipRule="evenodd"
                                      />
                                    </svg>
                                  </button>
                                )}
                              </td>
                              {/* Stay명 */}
                              <td className="px-4 py-3 text-sm font-medium text-gray-900 whitespace-nowrap">
                                <button
                                  type="button"
                                  onClick={() => copyToClipboard(item.stayName, 'STAY 명', '이')}
                                  title="클릭하여 복사"
                                  className="font-medium text-gray-900 hover:text-blue-600 transition-colors cursor-pointer"
                                >
                                  {item.stayName}
                                </button>
                              </td>
                              {/* 메모 */}
                              <td className="px-4 py-3 text-sm text-gray-600 max-w-[200px] truncate">
                                {item.note ? (
                                  <button
                                    type="button"
                                    onClick={() => copyToClipboard(item.note || '', '메모', '가')}
                                    title="클릭하여 복사"
                                    className="max-w-full truncate text-left text-gray-600 hover:text-blue-600 transition-colors cursor-pointer"
                                  >
                                    {item.note}
                                  </button>
                                ) : (
                                  <span className="text-gray-400 italic">-</span>
                                )}
                              </td>
                              {/* 호스트명 */}
                              <td className="px-4 py-3 text-sm text-gray-900 whitespace-nowrap">
                                {item.hostName}
                              </td>
                              {/* 생성일 */}
                              <td className="px-4 py-3 text-sm text-gray-600 whitespace-nowrap">
                                {formatDate(item.createdDate)}
                              </td>
                              {/* 설치일 */}
                              <td className="px-4 py-3 text-sm text-gray-600 whitespace-nowrap">
                                {item.installationDate || (
                                  <span className="text-gray-400 italic">-</span>
                                )}
                              </td>
                              {/* 상태 토글 */}
                              <td className="px-4 py-3 text-center">
                                <button
                                  type="button"
                                  disabled={item.active === null || togglingIds.has(item.id)}
                                  onClick={() => handleToggleClick(item)}
                                  className={`relative inline-flex h-6 w-11 flex-shrink-0 rounded-full border-2 border-transparent transition-colors duration-200 ease-in-out focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 ${
                                    item.active === null
                                      ? 'bg-gray-200 cursor-not-allowed'
                                      : item.active
                                        ? 'bg-emerald-500 cursor-pointer'
                                        : 'bg-gray-300 cursor-pointer'
                                  } ${togglingIds.has(item.id) ? 'opacity-60 cursor-wait' : ''}`}
                                  aria-pressed={item.active === true}
                                >
                                  <span
                                    className={`pointer-events-none inline-block h-5 w-5 transform rounded-full bg-white shadow ring-0 transition duration-200 ease-in-out ${
                                      item.active === true ? 'translate-x-5' : 'translate-x-0'
                                    }`}
                                  />
                                </button>
                              </td>
                              {/* QR / 포스터 */}
                              <td className="px-4 py-3 text-center">
                                <button
                                  onClick={() => handleQRCodeClick(item)}
                                  className="p-2 text-gray-500 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                                  title="QR 코드 / 포스터 다운로드"
                                >
                                  <svg
                                    className="w-5 h-5"
                                    fill="none"
                                    stroke="currentColor"
                                    viewBox="0 0 24 24"
                                  >
                                    <path
                                      strokeLinecap="round"
                                      strokeLinejoin="round"
                                      strokeWidth={2}
                                      d="M12 4v1m6 11h2m-6 0h-2v4m0-11v3m0 0h.01M12 12h4.01M16 20h2M4 12h4m12 0h.01M5 8h2a1 1 0 001-1V5a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1zm12 0h2a1 1 0 001-1V5a1 1 0 00-1-1h-2a1 1 0 00-1 1v2a1 1 0 001 1zM5 20h2a1 1 0 001-1v-2a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1z"
                                    />
                                  </svg>
                                </button>
                              </td>
                            </tr>
                            {/* 펼침 행: displayInfo */}
                            {expandedIds.has(item.id) && item.displayInfo && (
                              <tr className="bg-blue-50">
                                <td></td>
                                <td></td>
                                <td colSpan={7} className="px-4 py-3">
                                  <div className="text-sm">
                                    <span className="font-medium text-gray-700">표시 정보: </span>
                                    <span className="text-gray-600">{item.displayInfo}</span>
                                  </div>
                                </td>
                              </tr>
                            )}
                          </React.Fragment>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>

                {/* ── 모바일 카드 뷰 (md 미만) ── */}
                <div className="md:hidden space-y-3">
                  {/* 전체 선택 */}
                  <label className="flex items-center gap-2 px-1 py-2 text-sm text-gray-600">
                    <input
                      type="checkbox"
                      checked={stayList.length > 0 && selectedIds.length === stayList.length}
                      onChange={handleSelectAll}
                      className="w-4 h-4 text-blue-600 rounded border-gray-300 focus:ring-blue-500 cursor-pointer"
                    />
                    전체 선택
                  </label>

                  {stayList.map((item) => (
                    <div
                      key={item.id}
                      className={`bg-white rounded-lg shadow-sm border border-gray-200 p-4 ${item.active === false ? 'opacity-50' : ''}`}
                    >
                      {/* 카드 상단: 체크박스 + 순서 배지 + Stay명 + 토글 + QR 버튼 */}
                      <div className="flex items-start gap-3">
                        <div className="flex items-center gap-1.5 flex-shrink-0 mt-0.5">
                          <input
                            type="checkbox"
                            checked={selectedIds.includes(item.id)}
                            onChange={() => handleSelectItem(item.id)}
                            className="w-4 h-4 text-blue-600 rounded border-gray-300 focus:ring-blue-500 cursor-pointer"
                          />
                          {selectedIds.includes(item.id) && (
                            <span className="inline-flex items-center justify-center w-5 h-5 rounded-full bg-emerald-500 text-white text-[10px] font-bold leading-none">
                              {selectedIds.indexOf(item.id) + 1}
                            </span>
                          )}
                        </div>
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center justify-between gap-2">
                            <button
                              type="button"
                              onClick={() => copyToClipboard(item.stayName, 'STAY 명', '이')}
                              title="클릭하여 복사"
                              className="min-w-0 text-left text-sm font-semibold text-gray-900 truncate hover:text-blue-600 transition-colors cursor-pointer"
                            >
                              {item.stayName}
                            </button>
                            <div className="flex items-center gap-2 flex-shrink-0">
                              <button
                                type="button"
                                disabled={item.active === null || togglingIds.has(item.id)}
                                onClick={() => handleToggleClick(item)}
                                className={`relative inline-flex h-5 w-9 flex-shrink-0 rounded-full border-2 border-transparent transition-colors duration-200 ease-in-out focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 ${
                                  item.active === null
                                    ? 'bg-gray-200 cursor-not-allowed'
                                    : item.active
                                      ? 'bg-emerald-500 cursor-pointer'
                                      : 'bg-gray-300 cursor-pointer'
                                } ${togglingIds.has(item.id) ? 'opacity-60 cursor-wait' : ''}`}
                                aria-pressed={item.active === true}
                              >
                                <span
                                  className={`pointer-events-none inline-block h-4 w-4 transform rounded-full bg-white shadow ring-0 transition duration-200 ease-in-out ${
                                    item.active === true ? 'translate-x-4' : 'translate-x-0'
                                  }`}
                                />
                              </button>
                              <button
                                onClick={() => handleQRCodeClick(item)}
                                className="p-2 text-gray-500 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors flex-shrink-0"
                                title="QR 코드 / 포스터 다운로드"
                              >
                                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                  <path
                                    strokeLinecap="round"
                                    strokeLinejoin="round"
                                    strokeWidth={2}
                                    d="M12 4v1m6 11h2m-6 0h-2v4m0-11v3m0 0h.01M12 12h4.01M16 20h2M4 12h4m12 0h.01M5 8h2a1 1 0 001-1V5a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1zm12 0h2a1 1 0 001-1V5a1 1 0 00-1-1h-2a1 1 0 00-1 1v2a1 1 0 001 1zM5 20h2a1 1 0 001-1v-2a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1z"
                                  />
                                </svg>
                              </button>
                            </div>
                          </div>

                          {/* 호스트명 */}
                          <p className="text-xs text-gray-500 mt-0.5">
                            호스트: <span className="text-gray-700">{item.hostName}</span>
                          </p>

                          {/* 메모 */}
                          {item.note && (
                            <p className="text-xs text-gray-500 mt-1 truncate">
                              메모:{' '}
                              <button
                                type="button"
                                onClick={() => copyToClipboard(item.note || '', '메모', '가')}
                                title="클릭하여 복사"
                                className="text-left text-gray-600 hover:text-blue-600 transition-colors cursor-pointer"
                              >
                                {item.note}
                              </button>
                            </p>
                          )}

                          {/* 날짜 */}
                          <div className="flex flex-wrap gap-x-4 gap-y-1 mt-2 text-xs text-gray-500">
                            <span>생성: {formatDate(item.createdDate)}</span>
                            <span>설치: {item.installationDate || '-'}</span>
                          </div>

                          {/* displayInfo 토글 */}
                          {item.displayInfo && (
                            <div className="mt-2">
                              <button
                                onClick={() => toggleExpand(item.id)}
                                className="text-xs text-blue-600 hover:text-blue-800 flex items-center gap-1"
                              >
                                <svg
                                  className={`w-3 h-3 transform transition-transform ${
                                    expandedIds.has(item.id) ? 'rotate-90' : ''
                                  }`}
                                  fill="currentColor"
                                  viewBox="0 0 20 20"
                                >
                                  <path
                                    fillRule="evenodd"
                                    d="M7.293 14.707a1 1 0 010-1.414L10.586 10 7.293 6.707a1 1 0 111.414-1.414l4 4a1 1 0 010 1.414l-4 4a1 1 0 01-1.414 0z"
                                    clipRule="evenodd"
                                  />
                                </svg>
                                표시 정보
                              </button>
                              {expandedIds.has(item.id) && (
                                <div className="mt-1 p-2 bg-blue-50 rounded text-xs text-gray-600">
                                  {item.displayInfo}
                                </div>
                              )}
                            </div>
                          )}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </>
            ) : (
              <div className="bg-white rounded-lg shadow-sm p-8 text-center">
                <p className="text-gray-600">
                  {searchTerm
                    ? '검색 결과가 없습니다.'
                    : '등록된 Stay가 없습니다.'}
                </p>
              </div>
            )}
          </>
        )}
      </div>

      {/* 비활성화 확인 다이얼로그 */}
      {confirmDeactivate && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40">
          <div className="bg-white rounded-lg shadow-xl max-w-sm w-full mx-4 p-6">
            <h3 className="text-lg font-semibold text-gray-900 mb-2">Stay 비활성화</h3>
            <p className="text-sm text-gray-600 mb-6">
              <span className="font-medium">{confirmDeactivate.stayName}</span>을(를) 비활성화하시겠습니까?
              비활성화하면 해당 Stay에서 주문을 받을 수 없습니다.
            </p>
            <div className="flex justify-end gap-3">
              <button
                onClick={() => setConfirmDeactivate(null)}
                className="px-4 py-2 text-sm text-gray-700 bg-gray-100 rounded-lg hover:bg-gray-200 transition-colors"
              >
                취소
              </button>
              <button
                onClick={handleConfirmDeactivate}
                className="px-4 py-2 text-sm text-white bg-red-600 rounded-lg hover:bg-red-700 transition-colors"
              >
                비활성화
              </button>
            </div>
          </div>
        </div>
      )}

      {/* QR 코드 모달 */}
      {selectedStay && (
        <StayQRCodeModal
          isOpen={qrModalOpen}
          stay={selectedStay}
          onClose={handleQRModalClose}
        />
      )}

      {/* 숨김 QR 캔버스 (일괄 포스터 다운로드용) */}
      <div ref={qrContainerRef} className="hidden">
        {stayList.map((item) => (
          <div key={item.stayId} data-stay-id={item.stayId}>
            <QRCodeCanvas
              value={`https://koreaorder.com/stays/${item.stayId}`}
              size={400}
              level="M"
              marginSize={2}
              bgColor="#ffffff"
              fgColor="#000000"
            />
          </div>
        ))}
      </div>
    </div>
  );
};

export default StayManagementPage;
